CREATE TYPE "Role" AS ENUM ('OWNER','MANAGER','FULFILLMENT','CUSTOMER');
CREATE TYPE "ProductStatus" AS ENUM ('DRAFT','ACTIVE','ARCHIVED');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING_PAYMENT','PAID','PROCESSING','SHIPPED','DELIVERED','CANCELLED','REFUNDED');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','COMPLETED','FAILED','CANCELLED','REFUNDED');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"name" TEXT,"role" "Role" NOT NULL DEFAULT 'CUSTOMER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Address" ("id" TEXT NOT NULL,"userId" TEXT,"recipient" TEXT NOT NULL,"line1" TEXT NOT NULL,"line2" TEXT,"cityId" TEXT NOT NULL,"postalCode" TEXT NOT NULL,"phone" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Address_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"name" TEXT NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Product" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"categoryId" TEXT NOT NULL,"status" "ProductStatus" NOT NULL DEFAULT 'DRAFT',"verified" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductImage" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"url" TEXT NOT NULL,"alt" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "ProductImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductVariant" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"sku" TEXT NOT NULL,"label" TEXT NOT NULL,"priceCents" INTEGER NOT NULL,"weightGrams" INTEGER,CONSTRAINT "ProductVariant_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Inventory" ("id" TEXT NOT NULL,"variantId" TEXT NOT NULL,"onHand" INTEGER NOT NULL DEFAULT 0,"reserved" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "Inventory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "City" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"province" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"aliases" TEXT[],CONSTRAINT "City_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ShippingRate" ("id" TEXT NOT NULL,"cityId" TEXT NOT NULL,"courier" TEXT,"service" TEXT NOT NULL DEFAULT 'STANDARD',"feeCents" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"minWeightGrams" INTEGER,"maxWeightGrams" INTEGER,"validFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"validUntil" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ShippingRate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Order" ("id" TEXT NOT NULL,"orderNumber" TEXT NOT NULL,"userId" TEXT,"email" TEXT NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'PENDING_PAYMENT',"cityId" TEXT NOT NULL,"shippingRateId" TEXT,"shippingFeeCents" INTEGER NOT NULL,"subtotalCents" INTEGER NOT NULL,"totalCents" INTEGER NOT NULL,"addressSnapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"sku" TEXT NOT NULL,"productName" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unitPriceCents" INTEGER NOT NULL,"lineTotalCents" INTEGER NOT NULL,CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"provider" TEXT NOT NULL DEFAULT 'PAYFAST',"providerReference" TEXT,"amountCents" INTEGER NOT NULL,"status" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PaymentEvent" ("id" TEXT NOT NULL,"paymentId" TEXT NOT NULL,"eventKey" TEXT NOT NULL,"payload" JSONB NOT NULL,"verified" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PaymentEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug");
CREATE UNIQUE INDEX "Product_slug_key" ON "Product"("slug");
CREATE UNIQUE INDEX "ProductVariant_sku_key" ON "ProductVariant"("sku");
CREATE UNIQUE INDEX "Inventory_variantId_key" ON "Inventory"("variantId");
CREATE UNIQUE INDEX "City_province_normalizedName_key" ON "City"("province","normalizedName");
CREATE INDEX "ShippingRate_cityId_active_idx" ON "ShippingRate"("cityId","active");
CREATE UNIQUE INDEX "Order_orderNumber_key" ON "Order"("orderNumber");
CREATE UNIQUE INDEX "Payment_providerReference_key" ON "Payment"("providerReference");
CREATE UNIQUE INDEX "PaymentEvent_eventKey_key" ON "PaymentEvent"("eventKey");
ALTER TABLE "Address" ADD CONSTRAINT "Address_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Address" ADD CONSTRAINT "Address_cityId_fkey" FOREIGN KEY ("cityId") REFERENCES "City"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Product" ADD CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProductImage" ADD CONSTRAINT "ProductImage_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProductVariant" ADD CONSTRAINT "ProductVariant_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Inventory" ADD CONSTRAINT "Inventory_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "ProductVariant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ShippingRate" ADD CONSTRAINT "ShippingRate_cityId_fkey" FOREIGN KEY ("cityId") REFERENCES "City"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_cityId_fkey" FOREIGN KEY ("cityId") REFERENCES "City"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Order" ADD CONSTRAINT "Order_shippingRateId_fkey" FOREIGN KEY ("shippingRateId") REFERENCES "ShippingRate"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PaymentEvent" ADD CONSTRAINT "PaymentEvent_paymentId_fkey" FOREIGN KEY ("paymentId") REFERENCES "Payment"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
